using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace HexQuest
{
    /// <summary>
    /// Sound effects (pooled one-shots) and crossfading music loops, loaded from Resources/Audio
    /// (generated by tools/make_audio.py). Missing clips are silently skipped.
    /// </summary>
    public class AudioManager : MonoBehaviour
    {
        public static AudioManager Instance { get; private set; }

        AudioSource musicA, musicB, active;
        readonly List<AudioSource> pool = new List<AudioSource>();
        readonly Dictionary<string, AudioClip> clips = new Dictionary<string, AudioClip>();
        string currentMusic;
        Coroutine fade;

        public static AudioManager Create()
        {
            if (Instance != null) return Instance;
            var go = new GameObject("AudioManager");
            DontDestroyOnLoad(go);
            Instance = go.AddComponent<AudioManager>();
            return Instance;
        }

        void Awake()
        {
            musicA = NewSource(true);
            musicB = NewSource(true);
            active = musicA;
            for (int i = 0; i < 8; i++) pool.Add(NewSource(false));
        }

        AudioSource NewSource(bool loop)
        {
            var s = gameObject.AddComponent<AudioSource>();
            s.playOnAwake = false;
            s.loop = loop;
            s.spatialBlend = 0f;
            return s;
        }

        AudioClip Clip(string name)
        {
            AudioClip c;
            if (clips.TryGetValue(name, out c)) return c;
            c = Resources.Load<AudioClip>("Audio/" + name);
            clips[name] = c;
            return c;
        }

        public static void PlaySfx(string name, float volume = 1f, float pitchJitter = 0.04f)
        {
            if (Instance != null) Instance.Play(name, volume, pitchJitter);
        }

        public static void PlayMusic(string name)
        {
            if (Instance != null) Instance.SwitchMusic(name);
        }

        public static void RefreshVolumes()
        {
            if (Instance != null) Instance.ApplyMusicVolume();
        }

        void Play(string name, float volume, float pitchJitter)
        {
            var clip = Clip(name);
            if (clip == null) return;
            AudioSource src = null;
            foreach (var s in pool) if (!s.isPlaying) { src = s; break; }
            if (src == null) src = pool[0];
            src.pitch = 1f + Random.Range(-pitchJitter, pitchJitter);
            src.volume = volume * UserSettings.Master * UserSettings.Sfx;
            src.clip = clip;
            src.Play();
        }

        void ApplyMusicVolume()
        {
            if (active != null && active.isPlaying) active.volume = UserSettings.Master * UserSettings.Music * 0.7f;
        }

        void SwitchMusic(string name)
        {
            if (name == currentMusic) return;
            currentMusic = name;
            var clip = Clip(name);
            if (fade != null) StopCoroutine(fade);
            fade = StartCoroutine(Crossfade(clip));
        }

        IEnumerator Crossfade(AudioClip clip)
        {
            var from = active;
            var to = active == musicA ? musicB : musicA;
            if (clip != null)
            {
                to.clip = clip;
                to.volume = 0f;
                to.Play();
            }
            active = clip != null ? to : from;
            float t = 0f;
            float fromStart = from.volume;
            while (t < 1.2f)
            {
                t += Time.unscaledDeltaTime;
                float k = Mathf.Clamp01(t / 1.2f);
                float target = UserSettings.Master * UserSettings.Music * 0.7f;
                if (clip != null) to.volume = target * k;
                if (from != to) from.volume = fromStart * (1f - k);
                yield return null;
            }
            if (from != to) from.Stop();
        }
    }
}
